NAME\",1,LEN(\"EXPORT PARTY NAME\")-0),\'\') as \"EXPORT PARTY NAME\", NULLIF(SUBSTRING(\"EXPORT SHADE NAME\",1,LEN(\"EXPORT SHADE NAME\")-0),\'\') as \"EXPORT SHADE NAME\", NULLIF(SUBSTRING(\"IMPORT PARTY NAME\",1,LEN(\"IMPORT PARTY NAME\")-0),\'\') as \"IMPORT PARTY NAME\", NULLIF(SUBSTRING(\"EXPORT BRANCH NAME\",1,LEN(\"EXPORT BRANCH NAME\")-0),\'\') as \"EXPORT BRANCH NAME\", \"EXPORT GROSS VALUE\", NULLIF(SUBSTRING(\"IMPORT BRANCH NAME\",1,LEN(\"IMPORT BRANCH NAME\")-0),\'\') as \"IMPORT BRANCH NAME\", NULLIF(SUBSTRING(\"IMPORT GROSS VALUE\",1,LEN(\"IMPORT GROSS VALUE\")-0),\'\') as \"IMPORT GROSS VALUE\", NULLIF(SUBSTRING(\"EXPORT COMPANY NAME\",1,LEN(\"EXPORT COMPANY NAME\")-0),\'\') as \"EXPORT COMPANY NAME\", \"_AB_SOURCE_FILE_URL\", \"EXPORT AMOUNT(UD RATE)\", NULLIF(SUBSTRING(\"IMPORT AMOUNT(UD RATE)\",1,LEN(\"IMPORT AMOUNT(UD RATE)\")-0),\'\') as \"IMPORT AMOUNT(UD RATE)\", \"_AB_ADDITIONAL_PROPERTIES\", NULLIF(SUBSTRING(\"EXPORT ADDITIONAL ITEM CODE\",1,LEN(\"EXPORT ADDITIONAL ITEM CODE\")-0),\'\') as \"EXPORT ADDITIONAL ITEM CODE\", NULLIF(SUBSTRING(\"IMPORT ADDITIONAL ITEM CODE\",1,LEN(\"IMPORT ADDITIONAL ITEM CODE\")-0),\'\') as \"IMPORT ADDITIONAL ITEM CODE\", \"_AB_SOURCE_FILE_LAST_MODIFIED\", \"_AIRBYTE_AB_ID\", \"_AIRBYTE_EMITTED_AT\", \"_AIRBYTE_NORMALIZED_AT\", \"_AIRBYTE_OFFLINE_JIT_HASHID\" from data ) select * from clean ; Create or replace table snitch_db.maplemonk.final_puv_verification as SELECT _AIRBYTE_DATA:\"BARCODE\"::string AS \"BARCODE\", _AIRBYTE_DATA:\"BILL DATE\"::string AS \"BILL DATE\", _AIRBYTE_DATA:\"BILL NO.\"::string AS \"BILL NO.\", _AIRBYTE_DATA:\"BRANCH NAME\"::string AS \"BRANCH NAME\", _AIRBYTE_DATA:\"CATEGORY\"::string AS \"CATEGORY\", _AIRBYTE_DATA:\"CD VALUE\"::string AS \"CD VALUE\", _AIRBYTE_DATA:\"CD(%)\"::string AS \"CD(%)\", _AIRBYTE_DATA:\"CGST\"::string AS \"CGST\", _AIRBYTE_DATA:\"COMPANY NAME\"::string AS \"COMPANY NAME\", _AIRBYTE_DATA:\"FIT\"::string AS \"FIT\", _AIRBYTE_DATA:\"GRN NO.\"::string AS \"GRN NO.\", _AIRBYTE_DATA:\"GROSS VALUE\"::string AS \"GROSS VALUE\", _AIRBYTE_DATA:\"HSN GROUP\"::string AS \"HSN GROUP\", _AIRBYTE_DATA:\"ITEM CODE\"::string AS \"ITEM CODE\", _AIRBYTE_DATA:\"ITEM NAME\"::string AS \"ITEM NAME\", _AIRBYTE_DATA:\"NET AMOUNT\"::string AS \"NET AMOUNT\", _AIRBYTE_DATA:\"PO ORDER DATE\"::string AS \"PO ORDER DATE\", _AIRBYTE_DATA:\"PO ORDER NO.\"::string AS \"PO ORDER NO.\", _AIRBYTE_DATA:\"PRODUCT\"::string AS \"PRODUCT\", SPLIT_PART(_AIRBYTE_DATA:\"PUR QTY\", \',\', 1)::int AS \"PUR QTY\", _AIRBYTE_DATA:\"RATE\"::string AS \"RATE\", _AIRBYTE_DATA:\"RECEIPT DATE\"::string AS \"RECEIPT DATE\", _AIRBYTE_DATA:\"ROUND AMOUNT\"::string AS \"ROUND AMOUNT\", _AIRBYTE_DATA:\"SGST/IGST\"::string AS \"SGST/IGST\", _AIRBYTE_DATA:\"SIZE\"::string AS \"SIZE\", _AIRBYTE_DATA:\"SNO.\"::string AS \"SNO.\", _AIRBYTE_DATA:\"SUPPLIER NAME\"::string AS \"SUPPLIER NAME\", _AIRBYTE_DATA:\"TAX REGION\"::string AS \"TAX REGION\", _AIRBYTE_DATA:\"TAX-2(%)\"::string AS \"TAX-2(%)\", _AIRBYTE_DATA:\"TAX-2(RS)\"::string AS \"TAX-2(RS)\", _AIRBYTE_DATA:\"TAXABLE AMOUNT\"::string AS \"TAXABLE AMOUNT\", _AIRBYTE_DATA:\"GOODS IN TRANSIT\"::string AS \"GOODS IN TRANSIT\", _AIRBYTE_DATA:\"_ab_additional_properties\"::string AS \"_ab_additional_properties\", _AIRBYTE_DATA:\"_ab_source_file_last_modified\"::string AS \"_ab_source_file_last_modified\", _AIRBYTE_DATA:\"_ab_source_file_url\"::string AS \"_ab_source_file_url\" FROM snitch_db.maplemonk._AIRBYTE_RAW_puv_verification; CREATE or REPLACE TABLE SNITCH_DB.MAPLEMONK.JIT_OFFLINE_GOODS AS Select * from ( With final as (Select * from ( Select * from ( With overall as ( Select CASE WHEN POSITION(\'-\' IN \"ITEM CODE\") > 0 AND LEFT(\"ITEM CODE\", 2) = \'SH\' THEN SPLIT_PART(\"ITEM CODE\", \'-\', 1) WHEN POSITION(\'-\' IN \"ITEM CODE\") > 0 THEN SPLIT_PART(\"ITEM CODE\", \'-\', 1) || \'-\' || SPLIT_PART(\"ITEM CODE\", \'-\', 2) ELSE \"ITEM CODE\" END AS sku_group, \"ITEM CODE\", branch_code_priority , \"BRANCH NAME\", CASE WHEN \"RECEIPT DATE\" LIKE \'%/%/%\' THEN TO_DATE(\"RECEIPT DATE\", \'DD/MM/YYYY\') WHEN \"RECEIPT DATE\" LIKE \'%-%-%\' THEN TO_DATE(\"RECEIPT DATE\", \'DD-MM-YYYY\') ELSE NULL END AS Inward_date, SUM(\"PUR QTY\") AS qty, \'PUV Verification Pending\' as Status, DATEDIFF( DAY, inward_date, CURRENT_DATE ) AS aging from ( SELECT a.*, b.branch_code_priority FROM snitch_db.maplemonk.final_puv_verification a left join ( SELECT DISTINCT e.\"BRANCH NAME\", s.branch_code_priority FROM snitch_db.maplemonk.final_puv_verification e LEFT JOIN snitch_db.maplemonk.storepriority s ON e.\"BRANCH NAME\" LIKE \'%\' || s.branch_name_priority || \'%\') b on a.\"BRANCH NAME\" =b.\"BRANCH NAME\" where lower(\"GOODS IN TRANSIT\") = \'true\') GROUP BY 1,2,3,4,5 Union ALL SELECT CASE WHEN POSITION(\'-\' IN \"EXPORT ADDITIONAL ITEM CODE\") > 0 AND LEFT(\"EXPORT ADDITIONAL ITEM CODE\", 2) = \'SH\' THEN SPLIT_PART(\"EXPORT ADDITIONAL ITEM CODE\", \'-\', 1) WHEN POSITION(\'-\' IN \"EXPORT ADDITIONAL ITEM CODE\") > 0 THEN SPLIT_PART(\"EXPORT ADDITIONAL ITEM CODE\", \'-\', 1) || \'-\' || SPLIT_PART(\"EXPORT ADDITIONAL ITEM CODE\", \'-\', 2) ELSE \"EXPORT ADDITIONAL ITEM CODE\" END AS sku_group, \"EXPORT ADDITIONAL ITEM CODE\", branch_code_priority, \"EXPORT PARTY NAME\", CASE WHEN \"EXPORT DOC DATE\" LIKE \'%/%/%\' THEN TO_DATE(\"EXPORT DOC DATE\", \'DD/MM/YYYY\') WHEN \"EXPORT DOC DATE\" LIKE \'%-%-%\' THEN TO_DATE(\"EXPORT DOC DATE\", \'DD-MM-YYYY\') ELSE NULL END AS Inward_date, SUM(\"EXPORT QUANTITY\") AS QTY_JIT, \'IN TRANSIT\' AS STATUS, DATEDIFF( DAY, CASE WHEN \"EXPORT DOC DATE\" LIKE \'%/%/%\' THEN TO_DATE(\"EXPORT DOC DATE\", \'DD/MM/YYYY\') WHEN \"EXPORT DOC DATE\" LIKE \'%-%-%\' THEN TO_DATE(\"EXPORT DOC DATE\", \'DD-MM-YYYY\') ELSE NULL END, CURRENT_DATE ) AS aging FROM ( SELECT a.\"FIT\", a.\"SNO.\", a.\"BALANCE\", a.\"PRODUCT\", a.\"EXPORT TAX3\", a.\"IMPORT TAX3\", a.\"EXPORT DOC NO\", a.\"IMPORT DOC NO\", a.\"EXPORT DOC DATE\", a.\"EXPORT QUANTITY\", a.\"IMPORT DOC DATE\", a.\"IMPORT QUANTITY\", a.\"EXPORT ITEM CODE\", a.\"EXPORT ITEM NAME\", a.\"EXPORT NET VALUE\", a.\"EXPORT PACK SIZE\", a.\"IMPORT ITEM CODE\", a.\"IMPORT ITEM NAME\", a.\"IMPORT NET VALUE\", a.\"EXPORT GROUP NAME\", a.\"EXPORT PARTY NAME\", a.\"EXPORT SHADE NAME\", a.\"IMPORT PARTY NAME\", a.\"EXPORT BRANCH NAME\", a.\"EXPORT GROSS VALUE\", a.\"IMPORT BRANCH NAME\", a.\"IMPORT GROSS VALUE\", a.\"EXPORT COMPANY NAME\", a._AB_SOURCE_FILE_URL, a.\"EXPORT AMOUNT(UD RATE)\", a.\"IMPORT AMOUNT(UD RATE)\", a._AB_ADDITIONAL_PROPERTIES, a.\"EXPORT ADDITIONAL ITEM CODE\", a.\"IMPORT ADDITIONAL ITEM CODE\", a._AB_SOURCE_FILE_LAST_MODIFIED, a._AIRBYTE_AB_ID, a._AIRBYTE_EMITTED_AT, a._AIRBYTE_NORMALIZED_AT, a._AIRBYTE_OFFLINE_JIT_HASHID, b.branch_code_priority FROM snitch_db.maplemonk.offline_jit a LEFT JOIN ( SELECT DISTINCT e.\"EXPORT PARTY NAME\" AS \"EXPORT PARTY NAME\", case when e.\"EXPORT PARTY NAME\" =\'SNITCH - FOCO - C ROAD -JODHPUR\' then 39 when e.\"EXPORT PARTY NAME\" =\'SNITCH - COCO - LULU MALL TVM -TRIVNDRUM\' then 63 else s.branch_code_priority end branch_code_priority FROM snitch_db.maplemonk.offline_jit e LEFT JOIN snitch_db.maplemonk.storepriority s ON trim(REVERSE(SUBSTRING(REVERSE(e.\"EXPORT PARTY NAME\"), POSITION(\'-\', REVERSE(e.\"EXPORT PARTY NAME\")) + 1))) LIKE \'%\' || s.branch_name_priority || \'%\' where e.\"EXPORT DOC NO\" not in (\'2425/8/ST-3546\', \'2425/8/ST-3567\', \'2425/8/ST-3552\', \'2425/8/ST-3559\', \'2425/8/ST-3512\', \'2425/8/ST-3561\', \'2425/8/ST-3556\', \'2425/8/ST-3523\', \'2425/8/ST-3568\', \'2425/8/ST-3571\', \'2425/8/ST-3563\', \'2425/8/ST-3544\', \'2425/8/ST-3558\', \'2425/8/ST-3551\', \'2425/8/ST-3570\', \'2425/8/ST-3514\', \'2425/8/ST-3557\', \'2425/8/ST-3576\', \'2425/8/ST-3572\', \'2425/8/ST-3575\', \'2425/8/ST-3550\', \'2425/8/ST-3560\', \'2425/8/ST-3547\', \'2425/8/ST-3574\', \'2425/8/ST-3569\', \'2425/8/ST-3543\', \'2425/8/ST-3555\', \'2425/8/ST-3548\', \'2425/8/ST-3565\', \'2425/8/ST-3564\', \'2425/8/ST-3573\', \'2425/8/ST-3554\', \'2425/8/ST-3549\', \'2425/8/ST-3553\', \'2425/8/ST-3545\', \'2425/8/ST-3566\') ) b ON a.\"EXPORT PARTY NAME\" = b.\"EXPORT PARTY NAME\" WHERE (\"IMPORT QUANTITY\" = 0 OR \"IMPORT QUANTITY\" = \'\' OR \"IMPORT QUANTITY\" IS NULL) and \"EXPORT BRANCH NAME\" !=\'Bill Wise Totals\' and \"EXPORT BRANCH NAME\" !=\'GRAND Total\' and \"EXPORT DOC NO\" not in (\'2425/8/ST-3546\', \'2425/8/ST-3567\', \'2425/8/ST-3552\', \'2425/8/ST-3559\', \'2425/8/ST-3512\', \'2425/8/ST-3561\', \'2425/8/ST-3556\', \'2425/8/ST-3523\', \'2425/8/ST-3568\', \'2425/8/ST-3571\', \'2425/8/ST-3563\', \'2425/8/ST-3544\', \'2425/8/ST-3558\', \'2425/8/ST-3551\', \'2425/8/ST-3570\', \'2425/8/ST-3514\', \'2425/8/ST-3557\', \'2425/8/ST-3576\', \'2425/8/ST-3572\', \'2425/8/ST-3575\', \'2425/8/ST-3550\', \'2425/8/ST-3560\', \'2425/8/ST-3547\', \'2425/8/ST-3574\', \'2425/8/ST-3569\', \'2425/8/ST-3543\', \'2425/8/ST-3555\', \'2425/8/ST-3548\', \'2425/8/ST-3565\', \'2425/8/ST-3564\', \'2425/8/ST-3573\', \'2425/8/ST-3554\', \'2425/8/ST-3549\', \'2425/8/ST-3553\', \'2425/8/ST-3545\', \'2425/8/ST-3566\') and a.\"EXPORT PARTY NAME\" !=\'\' ) subquery where \"EXPORT PARTY NAME\" !=\'\' GROUP BY sku_group, \"EXPORT ADDITIONAL ITEM CODE\", branch_code_priority, \"EXPORT PARTY NAME\", Inward_date UNION ALL Select SKU_GROUP, SKU, BRANCH_CODE, store, ORDER_DATE, sum(qty) AS qty, status, datediff(day,order_date,current_date) as Aging From ( With over as ( Select SKU_GROUP, SKU, BRANCH_CODE, STATE_, ORDER_DATE, sum(JIT) AS qty, status, datediff(day,order_date,current_date) as Aging from ( Select * FROM ( SELECT jit.*, sd.branch_code, sd.STATE_, sd.type, sd.status, sd.Dispatch_date, sd.order_received_date, DATEDIFF(\'DAY\', sd.Dispatch_date, COALESCE(sd.order_received_date, CURRENT_DATE())) as Days_JIT FROM ( SELECT order_name, order_date, sku_group, SKU, SUM(stock_qty) AS JIT, COALESCE(SUM(CASE WHEN size_mapped = \'XS\' THEN stock_qty ELSE 0 END), 0) AS XS_units_store, COALESCE(SUM(CASE WHEN size_mapped = \'S\' THEN stock_qty ELSE 0 END), 0) AS S_units_store, COALESCE(SUM(CASE WHEN size_mapped = \'M\' THEN stock_qty ELSE 0 END), 0) AS M_units_store, COALESCE(SUM(CASE WHEN size_mapped = \'L\' THEN stock_qty ELSE 0 END), 0) AS L_units_store, COALESCE(SUM(CASE WHEN size_mapped = \'XL\' THEN stock_qty ELSE 0 END), 0) AS XL_units_store, COALESCE(SUM(CASE WHEN size_mapped IN (\'XXL\', \'XXl\', \'2XL\') THEN stock_qty ELSE 0 END), 0) AS XXL_units_store, COALESCE(SUM(CASE WHEN size_mapped = \'3XL\' THEN stock_qty ELSE 0 END), 0) AS XL3_units_store, COALESCE(SUM(CASE WHEN size_mapped = \'4XL\' THEN stock_qty ELSE 0 END), 0) AS XL4_units_store, COALESCE(SUM(CASE WHEN size_mapped = \'5XL\' THEN stock_qty ELSE 0 END), 0) AS XL5_units_store, COALESCE(SUM(CASE WHEN size_mapped = \'6XL\' THEN stock_qty ELSE 0 END), 0) AS XL6_units_store, COALESCE(SUM(CASE WHEN size_mapped = \'NA\' THEN stock_qty ELSE 0 END), 0) AS NA_units_store, (CASE WHEN XS_units_store > 0 THEN 1 ELSE 0 END) + (CASE WHEN S_units_store > 0 THEN 1 ELSE 0 END) + (CASE WHEN M_units_store > 0 THEN 1 ELSE 0 END) + (CASE WHEN L_units_store > 0 THEN 1 ELSE 0 END) + (CASE WHEN XL_units_store > 0 THEN 1 ELSE 0 END) + (CASE WHEN XXL_units_store > 0 THEN 1 ELSE 0 END) + (CASE WHEN XL3_units_store > 0 THEN 1 ELSE 0 END) + (CASE WHEN XL4_units_store > 0 THEN 1 ELSE 0 END) + (CASE WHEN XL5_units_store > 0 THEN 1 ELSE 0 END) + (CASE WHEN XL6_units_store > 0 THEN 1 ELSE 0 END)+ (CASE WHEN NA_units_store > 0 THEN 1 ELSE 0 END) AS num_size_available_REPLEN FROM ( SELECT order_name, order_date, CASE WHEN POSITION(\'-\' IN sku_group) > 0 AND LEFT(sku_group, 2) = \'SH\' THEN SPLIT_PART(sku_group, \'-\', 1) WHEN POSITION(\'-\' IN sku_group) > 0 THEN SPLIT_PART(sku_group, \'-\', 1) || \'-\' || SPLIT_PART(sku_group, \'-\', 2) ELSE sku_group END as sku_group, SKU, REVERSE(SUBSTRING(REVERSE(SKU), 1, POSITION(\'-\', REVERSE(SKU)) - 1)) AS size, sum(suborder_quantity) as stock_qty, CASE WHEN size = \'28\' THEN \'XS\' WHEN size = \'30\' THEN \'S\' WHEN size = \'32\' THEN \'M\' WHEN size = \'34\' THEN \'L\' WHEN size = \'36\' THEN \'XL\' WHEN size = \'38\' THEN \'XXL\' WHEN size = \'40\' THEN \'3XL\' WHEN size = \'42\' THEN \'4XL\' WHEN size = \'44\' THEN \'5XL\' WHEN size = \'46\' THEN \'6XL\' WHEN size = \'48\' THEN \'7XL\' WHEN size = \'50\' THEN \'8XL\' WHEN size = \'\' THEN \'NA\' WHEN size IS NULL THEN \'NA\' ELSE size END AS size_mapped FROM snitch_db.maplemonk.unicommerce_fact_items_intermediate_2024 WHERE SALE_ORDER_ITEM_STATUS not in (\'CANCELLED\',\'UNFULFILLABLE\') AND order_name IN ( SELECT DISTINCT so_number FROM snitch_db.maplemonk.INWARD_DATA WHERE STATUS not IN(\'Cancelled\',\'DUPLICATE\',\'Dispatched to Store\',\'Returned\',\'RTS-LOGIC\',\'UNFILFILLABLE\',\'E-SHIPZZ RTS\') ) GROUP BY order_name, sku_group, SKU, order_date order by stock_qty desc ) subquery GROUP BY order_name, SKU,sku_group, order_date HAVING SUM(stock_qty) > 0 ) jit LEFT JOIN ( Select Distinct so_number , BRANCH_CODE,STATE_, type, status, TO_DATE(REPLACE(ORDER_DISPATCHED_DATE,\'-\', \'/\'), \'DD/MM/YYYY\') as Dispatch_date, TO_DATE(REPLACE(order_received_date,\'-\', \'/\'), \'DD/MM/YYYY\') as order_received_date from snitch_db.maplemonk.INWARD_DATA WHERE STATUS not IN(\'Cancelled\',\'DUPLICATE\',\'Dispatched to Store\',\'Returned\',\'RTS-LOGIC\',\'UNFILFILLABLE\') ) sd ON jit.order_name = sd.so_number ) ) group by 1,2,3,4,5,7), dets as ( Select * from snitch_db.maplemonk.storepriority ) Select a.*, b.BRANCH_NAME_PRIORITY, coalesce(b.BRANCH_NAME_PRIORITY,a.state_) as Store from over a left join dets b on a.branch_code =b.BRANCH_CODE_PRIORITY ) group by 1,2,3,5,4,7 ) , deatilas as ( select * from ( select CASE WHEN POSITION(\'-\' IN sku_group) > 0 AND LEFT(sku_group, 2) = \'SH\' THEN SPLIT_PART(sku_group, \'-\', 1) WHEN POSITION(\'-\' IN sku_group) > 0 THEN SPLIT_PART(sku_group, \'-\', 1) || \'-\' || SPLIT_PART(sku_group, \'-\', 2) ELSE sku_group END as sku_group, product_name, category, final_ros, natural_ros, sku_class , ROW_NUMBER() OVER (PARTITION BY CASE WHEN POSITION(\'-\' IN sku_group) > 0 AND LEFT(sku_group, 2) = \'SH\' THEN SPLIT_PART(sku_group, \'-\', 1) WHEN POSITION(\'-\' IN sku_group) > 0 THEN SPLIT_PART(sku_group, \'-\', 1) || \'-\' || SPLIT_PART(sku_group, \'-\', 2) ELSE sku_group END ORDER BY 1) AS rn, from snitch_db.maplemonk.availability_master_v2) where rn=1 ) SELECT a.*, b.product_name, b.category, b.final_ros AS online_final_ros, b.natural_ros AS online_natural_ros, b.sku_class FROM overall a LEFT JOIN deatilas b ON a.SKU_GROUP = b.sku_group ) where sku_group not like \'%CB%\' ) ), haa as ( Select * from ( SELECT DISTINCT branch_code, marketplace_mapped, ROW_NUMBER() OVER (PARTITION BY branch_code ORDER BY order_date DESC) AS rn FROM snitch_db.maplemonk.STORE_fact_items_offline) WHERE rn = 1 ) Select a.SKU_GROUP, a.\"ITEM CODE\", a.INWARD_DATE, a.QTY, a.STATUS, a.AGING, a.PRODUCT_NAME, a.CATEGORY, a.ONLINE_FINAL_ROS, a.ONLINE_NATURAL_ROS, a.SKU_CLASS, CASE WHEN a.\"BRANCH NAME\" = \'SNITCH - COFO - INFINITY ANDHERI -MUMBAI\' THEN 28 WHEN a.\"BRANCH NAME\" = \'SNITCH - FOCO - C ROAD -JODHPUR\' THEN 40 WHEN a.\"BRANCH NAME\" = \'SNITCH - COFO - METRO MALL -KALYAN\' THEN 42 WHEN a.\"BRANCH NAME\" = \'SNITCH - FOCO - PALASSIO MALL -LUCKNKW\' THEN 48 WHEN a.\"BRANCH NAME\" = \'SNITCH - FOCO - PALASSIO MALL -LUCKNOW\' THEN 48 ELSE COALESCE(b.branch_code, a.branch_code_priority) END AS branch_code, CASE WHEN a.\"BRANCH NAME\" = \'SNITCH - COFO - INFINITY ANDHERI -MUMBAI\' THEN \'SNITCH - COFO - INFINITI ANDHERI\' WHEN a.\"BRANCH NAME\" = \'SNITCH - FOCO - C ROAD -JODHPUR\' THEN \'SNITCH - FOCO - C ROAD JODHPUR\' WHEN a.\"BRANCH NAME\" = \'SNITCH - COFO - METRO MALL -KALYAN\' THEN \'SNITCH - COFO - METRO MALL\' WHEN a.\"BRANCH NAME\" = \'SNITCH - FOCO - PALASSIO MALL -LUCKNKW\' THEN \'SNITCH - FOCO - PALASSIO MALL\' WHEN a.\"BRANCH NAME\" = \'SNITCH - FOCO - PALASSIO MALL -LUCKNOW\' THEN \'SNITCH - FOCO - PALASSIO MALL\' ELSE COALESCE(b.marketplace_mapped, a.\"BRANCH NAME\") END AS Store from final a left join haa b on a.branch_code_priority = b.branch_code ) ;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            